// Port of experiments/nlu/kb.py clean(): Colombian chat fillers that open or close a message
// ("ey parce, ...", "..., pues") carry no topic but dominate a short message's e5 embedding. The
// index vectors were embedded from cleaned texts, so the query must be cleaned the same way.
// Spec: __fixtures__/clean.json (generated by the exporter from kb.clean).

const FILLERS =
  'ey|ei|hey|oye|oiga|oigan|oe|ve|vea|uy|ay|ah|epa|hola|holi|buenas|buenos d[ií]as|buenas tardes|' +
  'buenas noches|parce|parcero|parcera|mano|manito|hermano|bro|mijo|mija|socio|amigo|amiga|' +
  'qu[eé] m[aá]s|quiubo|qu[eé] hubo|vos sab[eé]s|sab[eé]s|pues|porfa|por favor|una pregunta|' +
  'pregunta|disculpe|disculpa|me da pena pero|ome|che|y';

// Python's \b and \s are Unicode-aware for str patterns; JS needs the u flag and an explicit
// letter class for the word boundary after a filler.
const LEAD = new RegExp(
  `^(?:\\s*[¿¡,.!?;:-]*\\s*(?:${FILLERS})(?![\\p{L}\\p{N}_])[\\s,.!?;:-]*)+`,
  'iu',
);
const TRAIL = /[\s,]+(?:pues|parce|mano|porfa|o qu[eé]|bro)[\s?!.]*$/iu;

export function clean(text: string): string {
  const t = text.replace(LEAD, '').replace(TRAIL, '').trim();
  return [...t].length >= 3 ? t : text;
}
